    //    "icon":"https://polymarket-upload.s3.us-east-2.amazonaws.com/will-trump-visit-china-by-october-31-ujqWMja0Uizt.png",
    //    "description":"If U.S. President Donald Trump visits China by October
    //    31, 2025, 11:59 PM ET, this market will resolve to \\""Yes\\"".
    //    Otherwise, this market will resolve to \\""No\\"".\\n\\nFor the
    //    purpose of this market, a \\""visit\\"" is defined as Trump physically
    //    entering the terrestrial or maritime territory of the listed country.
    //    Whether or not Trump enters the country's airspace during the
    //    timeframe of this market will have no bearing on a positive
    //    resolution.\\n\\nThe primary resolution source for this information
    //    will be official information from government of the United States of
    //    America, official information from Trump or released by his verified
    //    social media accounts (e.g. https://twitter.com/POTUS), however, a
    //    consensus of credible reporting will also be used.",
    //    "outcomes":"[\\""Yes\\"", \\""No\\""]",
    //    "outcomePrices":"[\\"0\\", \\"1\\"]",
    //    "volume":"549414.493468",
    //    "active":true,
    //    "closed":true,
    //    "marketMakerAddress":"",
    //    "createdAt":"2025-09-19T19:32:28.841694Z",
    //    "updatedAt":"2026-03-09T22:44:28.896812Z",
    //    "closedTime":"2025-11-01 06:28:08+00",
    //    "new":false,
    //    "featured":false,
    //    "submitted_by":"0x91430CaD2d3975766499717fA0D66A78D814E5c5",
    //    "archived":false,
    //    "resolvedBy":"0x65070BE91477460D8A7AeEb94ef92fe056C2f2A7",
    //    "restricted":true,
    //    "groupItemTitle":"October 31, 2025",
    //    "groupItemThreshold":"0",
    //    "questionID":"0x2dd49c70f01a5e7c687a9820d606ff0d85fb50199735928d52d98b3a57586969",
    //    "umaEndDate":"2025-11-01T06:28:08Z",
    //    "enableOrderBook":true,
    //    "orderPriceMinTickSize":"0.001",
    //    "orderMinSize":"5",
    //    "umaResolutionStatus":"resolved",
    //    "volumeNum":"549414.493468",
    //    "endDateIso":"2025-10-31",
    //    "startDateIso":"2025-09-19",
    //    "hasReviewedDates":true,
    //    "volume1wk":"121949.66579699998",
    //    "volume1mo":"535231.3545640002",
    //    "volume1yr":"549414.4934680002",
    //    "clobTokenIds":"[\\"45601394554497090173642354630373884477724604907691447337031201817815960365378\\",
    //    \\"102652665954921241745169157447280060113772926009745753029489061659654862632571\\"]",
    //    "umaBond":"500",
    //    "umaReward":"5",
    //    "volume1wkClob":"121949.66579699998",
    //    "volume1moClob":"535231.3545640002",
    //    "volume1yrClob":"549414.4934680002",
    //    "volumeClob":"549414.493468",
    //    "customLiveness":"0",
    //    "acceptingOrders":false,
    //    "negRisk":false,
    //    "negRiskRequestID":"",
    //    "ready":false,
    //    "funded":false,
    //    "acceptingOrdersTimestamp":"2025-09-19T21:22:32Z",
    //    "cyom":false,
    //    "pagerDutyNotificationEnabled":false,
    //    "approved":true,
    //    "rewardsMinSize":"100",
    //    "rewardsMaxSpread":"3.5",
    //    "spread":"0.001",
    //    "automaticallyResolved":true,
    //    "oneDayPriceChange":"-0.0005",
    //    "oneWeekPriceChange":"-0.007",
    //    "oneMonthPriceChange":"-0.011",
    //    "lastTradePrice":"1",
